import{_ as n,q as a,s,J as t}from"./framework-4ff91fa4.js";const e={},o=t(`<h2 id="常见类型" tabindex="-1"><a class="header-anchor" href="#常见类型" aria-hidden="true">#</a> 常见类型</h2><table><thead><tr><th>类型</th><th>用途</th><th>示例</th></tr></thead><tbody><tr><td>Byte / Short / Int / Long</td><td>不同范围的整数</td><td><code>42</code>、<code>42L</code></td></tr><tr><td>Float / Double</td><td>浮点数</td><td><code>3.5f</code>、<code>3.5</code></td></tr><tr><td>Boolean</td><td>真或假</td><td><code>true</code></td></tr><tr><td>Char</td><td>单个 UTF-16 字符单元</td><td><code>&#39;中&#39;</code></td></tr><tr><td>String</td><td>文本</td><td><code>&quot;你好&quot;</code></td></tr></tbody></table><p>整数默认通常推断为 Int，超出范围时可能推断为 Long。小数默认是 Double。下划线可改善长数字的可读性，如 <code>1_000_000</code>。</p><h2 id="转换需要显式表达" tabindex="-1"><a class="header-anchor" href="#转换需要显式表达" aria-hidden="true">#</a> 转换需要显式表达</h2><div class="language-kotlin line-numbers-mode" data-ext="kt"><pre class="language-kotlin"><code><span class="token keyword">fun</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">val</span> count<span class="token operator">:</span> Int <span class="token operator">=</span> <span class="token number">7</span>
    <span class="token keyword">val</span> large<span class="token operator">:</span> Long <span class="token operator">=</span> count<span class="token punctuation">.</span><span class="token function">toLong</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token function">println</span><span class="token punctuation">(</span>large<span class="token punctuation">)</span>
    <span class="token function">println</span><span class="token punctuation">(</span><span class="token number">7</span> <span class="token operator">/</span> <span class="token number">2</span><span class="token punctuation">)</span>          <span class="token comment">// 3，整数除法</span>
    <span class="token function">println</span><span class="token punctuation">(</span><span class="token number">7</span> <span class="token operator">/</span> <span class="token number">2.0</span><span class="token punctuation">)</span>        <span class="token comment">// 3.5</span>
    <span class="token function">println</span><span class="token punctuation">(</span><span class="token string-literal singleline"><span class="token string">&quot;12&quot;</span></span><span class="token punctuation">.</span><span class="token function">toIntOrNull</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token comment">// 12</span>
    <span class="token function">println</span><span class="token punctuation">(</span><span class="token string-literal singleline"><span class="token string">&quot;abc&quot;</span></span><span class="token punctuation">.</span><span class="token function">toIntOrNull</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token comment">// null</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>把 Double 转成 Int 会截去小数部分，不等于四舍五入；大数转小类型可能丢失信息。处理外部输入时，优先使用 <code>toIntOrNull()</code> 一类可失败的解析。</p><h2 id="精度与边界" tabindex="-1"><a class="header-anchor" href="#精度与边界" aria-hidden="true">#</a> 精度与边界</h2><p>浮点数不能精确表示所有十进制小数，金额可以使用最小货币单位的 Long，或 JVM 的 BigDecimal，并制定舍入规则。整数溢出通常不会自动报错，选择类型时要估算数据范围。</p><p><code>Any</code> 是非空类型体系的通用父类型；<code>Any?</code> 还能容纳 null。<code>Unit</code> 表示函数没有有意义的结果，<code>Nothing</code> 表示执行不会正常返回，例如始终抛异常的函数。</p><h2 id="无符号整数" tabindex="-1"><a class="header-anchor" href="#无符号整数" aria-hidden="true">#</a> 无符号整数</h2><p>UByte、UShort、UInt 和 ULong 表示无符号整数，例如 <code>val mask: UInt = 255u</code>、<code>val id: ULong = 42uL</code>。不要与有符号类型随意混算；转换仍需显式处理范围。某些无符号数组 API 可能需要 opt-in，按所用编译器的诊断选择使用。</p><h2 id="动手练习" tabindex="-1"><a class="header-anchor" href="#动手练习" aria-hidden="true">#</a> 动手练习</h2><p>预测 5 / 2、5 / 2.0 和 2.9.toInt() 的结果。</p><details><summary>查看参考思路</summary><p>依次是 2、2.5、2。最后一个操作直接截去小数部分。</p></details><h2 id="延伸阅读" tabindex="-1"><a class="header-anchor" href="#延伸阅读" aria-hidden="true">#</a> 延伸阅读</h2><p><a href="https://kotlinlang.org/docs/numbers.html" target="_blank" rel="noopener noreferrer">Kotlin 官方文档：numbers</a>。本章为原创中文学习笔记，示例以 Kotlin/JVM 为主；使用扩展库的章节需先配置依赖。</p>`,16),p=[o];function c(l,d){return a(),s("div",null,p)}const r=n(e,[["render",c],["__file","types.html.vue"]]);export{r as default};
